setSelfShip(state: { classId: string; pos: Vec3; rot: {x,y,z,w}; livery?: Livery | null } | null): void {
  if (!state) {
    this.disposeSelfShip();
    return;
  }
  const quat = state.rot;
  if (!this.selfShip || this.selfShip.classId !== state.classId) {
