    const mesh = buildShipMesh(state.classId);
    this.selfShip = mesh;
    this.selfShipLiveryKey = liveryKey(state.livery);
    this.scene.add(mesh.group);
  }
  if (this.selfShipLiveryKey !== liveryKey(state.livery)) {
    this.selfShipLiveryKey = liveryKey(state.livery);
    applyLivery(this.selfShip, state.livery ?? null);
  }
  this.selfShip.group.position.set(state.pos.x, state.pos.y, state.pos.z);
  this.selfShip.group.quaternion.set(quat.x, quat.y, quat.z, quat.w);
