const localAhead = { x: 0, y: 0, z: CHASE_LOOK_AHEAD };
const expectPos = pos + quatRotate(q, localOffset)
const expectLook = pos + quatRotate(q, localAhead)
expect position ≈ expectPos
expect look ≈ expectLook
```

